"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import { LayoutDashboard, BarChart3, Boxes, Bell, Menu } from "lucide-react"
import { cn } from "@/lib/utils"
import { useSidebar } from "@/contexts/sidebar-context"

const navItems = [
    {
        href: "/dashboard",
        label: "Overview",
        icon: LayoutDashboard,
        activeIcon: LayoutDashboard // Could use filled variants if available
    },
    {
        href: "/dashboard/analytics",
        label: "Analytics",
        icon: BarChart3,
        activeIcon: BarChart3
    },
    {
        href: "/dashboard/widgets",
        label: "Widgets",
        icon: Boxes,
        activeIcon: Boxes
    },
    {
        href: "/dashboard/notifications",
        label: "Notifications",
        icon: Bell,
        activeIcon: Bell
    },
]

export function MobileNav() {
    const pathname = usePathname()
    const { setMobileOpen } = useSidebar()

    const handleMenuClick = () => {
        setMobileOpen(true)
    }

    return (
        <nav
            className={cn(
                "fixed bottom-0 left-0 right-0 z-50",
                "md:hidden", // Only visible on mobile
                "bg-background/80 backdrop-blur-md border-t border-border",
                "mobile-nav-safe" // Safe area insets
            )}
            style={{
                paddingBottom: "env(safe-area-inset-bottom, 0px)"
            }}
        >
            <div className="flex items-center justify-around px-2 py-2">
                {navItems.map((item) => {
                    const isActive = pathname === item.href || (item.href !== "/dashboard" && pathname.startsWith(item.href + "/"))
                    const Icon = isActive ? item.activeIcon : item.icon

                    return (
                        <Link
                            key={item.href}
                            href={item.href}
                            className={cn(
                                "flex flex-col items-center justify-center gap-1 px-3 py-2 rounded-lg transition-all duration-200",
                                "min-w-[64px] min-h-[56px]", // Ensure 44px+ touch target
                                "hover:bg-accent/50 active:scale-95",
                                isActive
                                    ? "text-primary font-medium"
                                    : "text-muted-foreground hover:text-foreground"
                            )}
                        >
                            <Icon
                                className={cn(
                                    "h-5 w-5 transition-transform duration-200",
                                    isActive && "scale-110"
                                )}
                                strokeWidth={isActive ? 2.5 : 2}
                            />
                            <span className="text-xs truncate max-w-[64px]">{item.label}</span>
                        </Link>
                    )
                })}

                {/* Menu Button - Opens Sidebar */}
                <button
                    onClick={handleMenuClick}
                    className={cn(
                        "flex flex-col items-center justify-center gap-1 px-3 py-2 rounded-lg transition-all duration-200",
                        "min-w-[64px] min-h-[56px]", // Ensure 44px+ touch target
                        "text-muted-foreground hover:text-foreground hover:bg-accent/50 active:scale-95"
                    )}
                >
                    <Menu className="h-5 w-5" strokeWidth={2} />
                    <span className="text-xs">Menu</span>
                </button>
            </div>
        </nav>
    )
}
